#include "recovery_manager.hpp"
namespace exotic::autonomy::persistence {
RecoveryReport RecoveryManager::recover(){RecoveryReport r;auto os=repository_.load_objectives();auto ps=repository_.load_proposals();auto ops=repository_.load_operations();r.objectives_loaded=os.size();r.proposals_loaded=ps.size();r.operations_loaded=ops.size();for(auto&o:ops){if(o.status!=OperationStatus::Running&&o.status!=OperationStatus::Verifying)continue;o.status=OperationStatus::Interrupted;o.failure_reason="Operation was interrupted by process shutdown.";o.execution_trace.push_back("Recovery manager marked operation as interrupted.");repository_.save_operation(o);AuditEvent e;e.id=repository_.next_audit_event_id();e.event_type="operation.interrupted";e.entity_type="operation";e.entity_id=o.id;e.actor="exotic.recovery";e.message="In-flight operation was recovered after restart.";repository_.append_audit_event(e);++r.interrupted_operations;r.interrupted_operation_ids.push_back(o.id);}return r;}
}
